import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>PNG'yi WebP'ye dönüştürmek birkaç dakikalık bir iştir. Program kurmazsınız, dosyanız cihazınızdan ayrılmaz ve sonunda çok daha hafif bir görsel indirirsiniz.</p>\n<p>Bu yazı, işlemi altı adımda anlatıyor. İster tek bir logo ister bütün bir simge seti dönüştürün, adımlar aynıdır.</p>\n<p>Sonunda saydamlığı nasıl doğrulayacağınızı, kaliteyi nasıl değiştireceğinizi ve yaygın sorunları nasıl çözeceğinizi de öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: neler gerekli</h2>\n<p>Tek ihtiyacınız, dönüştürülecek PNG dosyaları ve modern bir tarayıcıdır. Dosyalarınızın nerede olduğunu bilin; masaüstünde ya da indirilenler klasöründe olabilirler.</p>\n<p>Orijinal PNG'lerin bir yedeğini alın. Dönüştürmeden sonra WebP'den mükemmel bir PNG geri üretilemez; orijinaller güvenlik ağınızdır.</p>\n<p>Hedefi belirleyin: logo mu, simge seti mi, ekran görüntüsü mü? Hedef, kalite ayarını seçmenizi kolaylaştırır.</p>\n<h2 id=\"step-1-open-tool\">Adım 1: PNG'den WebP'ye aracını açın</h2>\n<p>Tarayıcınızda PNG'den WebP'ye aracını açın. Sayfa hemen yüklenir; hesap açmanız ya da program kurmanız gerekmez.</p>\n<p>Araç tamamen tarayıcıda çalışır. Dosyalarınız sunucuya yüklenmez, bu yüzden gizli ya da müşteri işlerini güvenle dönüştürebilirsiniz.</p>\n<h2 id=\"step-2-upload\">Adım 2: PNG dosyalarınızı yükleyin</h2>\n<p>Dosyaları yükleme alanına sürükleyin ya da dosya seçiciyle seçin. Birden fazla PNG'yi aynı anda seçebilirsiniz.</p>\n<p>Dosyalar listede görünür; her birinin adı ve boyutu yazılır. Yanlış bir dosya eklediyseniz listeden kaldırabilirsiniz.</p>\n<h2 id=\"step-3-quality\">Adım 3: kalite ayarını yapın</h2>\n<p>Kalite kaydırıcısını hedefinize göre ayarlayın. Logolar için yüzde 85, ekran görüntüleri için yüzde 80 iyi bir başlangıçtır.</p>\n<p>Kalite düştükçe dosya küçülür ama kenarlar bozulur. Önizlemeyi izleyin; metin ve ince çizgiler bulanıklaşmaya başlarsa kaliteyi artırın.</p>\n<h2 id=\"step-4-convert\">Adım 4: dosyaları dönüştürün</h2>\n<p>Dönüştür düğmesine basın. Araç her dosyayı sırayla işler; ilerleme çubuğu durumu gösterir.</p>\n<p>Dönüştürme genellikle birkaç saniye sürer. Büyük dosyalar ya da kalabalık listeler biraz daha uzun sürebilir.</p>\n<h2 id=\"step-5-verify-transparency\">Adım 5: saydamlığın korunduğunu doğrulayın</h2>\n<p>Dönüştürmeden sonra önizlemeyi açın. Saydam alanlar damalı desenle gösterilir; logonun köşeleri temiz olmalıdır.</p>\n<p>Karşılaştırma görünümüyle orijinali ve WebP'yi yan yana inceleyin. Kenarlarda beyaz hale ya da renk kayması görürseniz kaliteyi artırıp yeniden dönüştürün.</p>\n<h2 id=\"step-6-download\">Adım 6: WebP dosyalarını indirin</h2>\n<p>Her dosyayı tek tek indirebilir ya da tamamını ZIP olarak alabilirsiniz. ZIP, simge setleri için çok pratiktir.</p>\n<p>İndirilen dosyaların adlarını kontrol edin. Orijinal ad korunur, yalnızca uzantı .webp olur; böylece referansları güncellemek kolaylaşır.</p>\n<ol>\n<li>PNG'den WebP'ye aracını açın ve PNG dosyalarınızı yükleyin.</li>\n<li>Kaliteyi logolar için yüzde 85 olarak ayarlayın.</li>\n<li>Dönüştürün ve saydamlığı karşılaştırma görünümüyle doğrulayın.</li>\n<li>WebP dosyalarını tek tek ya da toplu olarak ZIP ile indirin.</li>\n</ol>\n<h2 id=\"converting-an-icon-set\">Bir simge setinin tamamını dönüştürmek</h2>\n<p>Tüm simge PNG'lerini dosya seçicide aynı anda seçin. Yüklenirler ve tek tıklamayla hepsi WebP olur.</p>\n<p>Tüm sette aynı kalite ayarını kullanın. Tutarlılık, simgelerin uygulamanın her yerinde aynı görünmesini sağlar.</p>\n<p>Dönüştürmeden sonra simgeleri boyutlarına göre kontrol edin. Minik simgelerde WebP bazen PNG'den büyük çıkabilir; o boyutlarda PNG'yi koruyun.</p>\n<h2 id=\"changing-quality-after\">Dönüştürmeden sonra kaliteyi değiştirmek</h2>\n<p>Kaliteyi beğenmediyseniz yeniden yüklemenize gerek yok. Aynı dosyalar listede dururken kaliteyi değiştirip yeniden dönüştürebilirsiniz.</p>\n<p>Önce düşük kaliteyi deneyin, sonra artırın. Böylece dosya boyutu ile görsel kalite arasındaki en iyi dengeyi hızlı bulursunuz.</p>\n<p>Her denemede önizlemeyi karşılaştırın. Gözle görünür fark yoksa daha küçük dosyayı seçin; fark varsa kaliteyi artırın.</p>\n<h2 id=\"fixing-problems\">Yaygın sorunları çözmek</h2>\n<p>Dosya yüklenmiyorsa boyut sınırını kontrol edin. Araç 20 MB'a kadar dosyaları kabul eder; daha büyük dosyaları önce sıkıştırın.</p>\n<p>Saydam alan beyaz görünüyorsa dosya gerçekten saydam olmayabilir. Orijinal PNG'yi kontrol edin; bazı PNG'ler beyaz arka planla kaydedilir.</p>\n<p>Dönüştürülen dosya çok büyükse kaliteyi düşürün. Yüzde 80'den 75'e inmek genellikle görünür fark yaratmadan boyutu belirgin küçültür.</p>\n<h2 id=\"uploading-to-your-site\">WebP'yi sitenize yüklemek</h2>\n<p>WebP dosyalarını sitenize PNG'ler gibi yükleyin. Çoğu modern içerik yönetim sistemi WebP'yi doğrudan kabul eder.</p>\n<p>Eski tarayıcılar için picture öğesi kullanın. Önce WebP kaynağını, sonra JPG yedeğini koyun; her ziyaretçi görseli görür.</p>\n<p>Yükledikten sonra sayfayı eski bir tarayıcıda da test edin. Görsel görünmüyorsa yedek kaynağı kontrol edin.</p>\n<h2 id=\"converting-logo-website\">Bir web sitesi için logo dönüştürmek</h2>\n<p>Logo için kaliteyi yüzde 85-90 arasında tutun. Marka işareti piksel piksel aynı kalmalıdır; burada birkaç KB tasarruf riske değmez.</p>\n<p>Logonun açık ve koyu zemin sürümlerini ayrı dönüştürün. Her sürümü kendi arka planında kontrol edin.</p>\n<p>Logoyu sitenin üstbilgisinde test edin. Küçük boyutta bile keskin görünmelidir; bulanıklık varsa kaliteyi artırın.</p>\n<h2 id=\"converting-icons-app\">Bir uygulama için simge dönüştürmek</h2>\n<p>Uygulama simgelerini gereken her boyutta dönüştürün. Kaynak PNG yüksek çözünürlüklü olmalıdır; küçük kaynaktan büyük simge üretilemez.</p>\n<p>Tüm boyutlarda aynı kalite ayarını kullanın. Böylece simge seti tutarlı görünür.</p>\n<p>Simgeleri uygulamada test edin. Küçük boyutlarda kenarların temiz kaldığını doğrulayın.</p>\n<h2 id=\"converting-screenshots-blog\">Blog için ekran görüntüsü dönüştürmek</h2>\n<p>Ekran görüntülerinde kaliteyi yüzde 85'in altına indirmeyin. Metin okunaklı kalmalıdır; bulanık yazı okuru uzaklaştırır.</p>\n<p>Dönüştürme öncesi ve sonrası yüzde 100 yakınlaştırarak karşılaştırın. Küçük yazılardaki bulanıklık yalnızca tam boyutta belli olur.</p>\n<p>Blog yazısındaki tüm görselleri toplu dönüştürün. On görselli bir yazı toplamda birkaç MB kazanabilir.</p>\n<h2 id=\"converting-product-images\">Ürün görseli dönüştürmek</h2>\n<p>Ürün fotoğraflarında kaliteyi yüzde 80-85 arasında tutun. Müşteri ürünü net görmelidir; bulanık ürün fotoğrafı güven kaybettirir.</p>\n<p>Küçük resim ve büyük görsel için ayrı kalite kullanın. Küçük resimde yüzde 75 yeterliyken, yakınlaştırılan büyük görselde yüzde 85 daha güvenlidir.</p>\n<p>Ürün sayfasını yükledikten sonra kontrol edin. Görseller hızlı açılmalı ve renkler doğru görünmelidir.</p>\n<h2 id=\"converting-presentation-images\">Sunum için görsel dönüştürmek</h2>\n<p>Sunum görsellerinde kaliteyi yüzde 85 tutun. Projektörde gösterilecek görsellerde bulanıklık hemen fark edilir.</p>\n<p>Sunum programınızın WebP destekleyip desteklemediğini kontrol edin. Bazı eski sürümler WebP göstermez; o durumda JPG kullanın.</p>\n<p>Sunumdan önce dosyaları çevrimdışı test edin. Salonun bilgisayarında görselin açıldığından emin olun.</p>\n<h2 id=\"converting-client-brand-assets\">Müşterinin marka dosyalarını dönüştürmek</h2>\n<p>Müşteri dosyalarında orijinalleri asla silmeyin. Dönüştürülen WebP'leri ayrı bir klasörde teslim edin.</p>\n<p>Müşteriye hangi ayarı kullandığınızı söyleyin. Şeffaf bir teslimat, müşterinin dosyaları ileride yeniden üretmesini kolaylaştırır.</p>\n<p>Teslimattan önce tüm dosyaları kontrol edin. Saydamlık, boyut ve adlandırmayı tek tek doğrulayın.</p>\n<h2 id=\"webp-for-online-courses\">Çevrimiçi kurslar için WebP</h2>\n<p>Kurs platformlarında görseller hızlı yüklenmelidir. WebP, ders sayfalarını hafifletir ve öğrencinin beklemesini azaltır.</p>\n<p>Ders görsellerinde kaliteyi yüzde 80-85 tutun. Diyagramlardaki yazılar okunaklı kalmalıdır.</p>\n<p>Platformun WebP kabul edip etmediğini kontrol edin. Kabul etmiyorsa JPG kullanın; uyumluluk her zaman önce gelir.</p>\n<p>Adım adım ilerleyin ve her dosyayı indirmeden önce kontrol edin. Kılavuzun tamamı için <a href=\"/tr/blog/png-webp-ye-donustur-rehberi\">PNG'den WebP'ye kılavuzuna</a> bakın; format karşılaştırması için <a href=\"/tr/blog/png-vs-webp\">PNG ve WebP karşılaştırması</a> yardımcı olur. Saydamlık gerekmiyorsa <a href=\"/tr/png-jpg-ye-donustur\">PNG'den JPG'ye dönüştürücü</a> de elinizin altındadır; araç ise <a href=\"/tr/png-webp-ye-donustur\">PNG'den WebP'ye dönüştürücü</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Dönüştürmeden sonra saydamlığın korunduğunu nasıl doğrularım?","answer":"Önizlemede saydam alanlar damalı desenle gösterilir; logonun köşelerinin temiz kaldığını kontrol edin. Karşılaştırma görünümüyle orijinal PNG ile WebP'yi yan yana inceleyin. Beyaz hale ya da renk kayması görürseniz kaliteyi artırıp yeniden dönüştürün."},{"question":"PNG ekran görüntülerini metin bulanıklaşmadan WebP'ye dönüştürebilir miyim?","answer":"Evet, kaliteyi yüzde 85'in altına indirmeyin. Bu seviyede yazılar keskin kalır ve dosya yine de belirgin küçülür. Dönüştürmeden önce ve sonra yüzde 100 yakınlaştırmayla karşılaştırın; küçük yazılardaki bulanıklık ancak tam boyutta belli olur."},{"question":"Dönüştürme için kabul edilen en büyük PNG boyutu nedir?","answer":"Araç 20 MB'a kadar dosyaları kabul eder. Daha büyük dosyaları önce sıkıştırmanız gerekir. Çoğu logo, simge ve ekran görüntüsü bu sınırın çok altındadır; sınır genellikle yalnızca çok yüksek çözünürlüklü fotoğraflarda sorun olur."},{"question":"Dönüştürdükten sonra kaliteyi yeniden yüklemeden değiştirebilir miyim?","answer":"Evet. Dosyalar listede dururken kalite kaydırıcısını değiştirip yeniden dönüştürebilirsiniz. Önce düşük kaliteyi deneyin, sonra artırın; böylece dosya boyutu ile görsel kalite arasındaki en iyi dengeyi hızlı bulursunuz."},{"question":"PNG'den WebP'ye dönüştürme mobil tarayıcılarda çalışır mı?","answer":"Evet, modern mobil tarayıcılar aracı tam olarak destekler. Telefonda dosya seçip dönüştürebilir ve sonucu indirebilirsiniz. Yine de çok sayıda dosyayı dönüştürmek bilgisayarda daha rahat olur; toplu işler için masaüstünü tercih edin."},{"question":"PNG'den WebP'ye yerine PNG'den JPG'ye ne zaman seçmeliyim?","answer":"Görselde saydamlık varsa ya da web sitesinde kullanılacaksa WebP'yi seçin; WebP alfa kanalını korur ve daha küçük dosyalar üretir. Hedef form, yazıcı ya da e-postaysa JPG'yi seçin; bu sistemlerde uyumluluk boyuttan daha önemlidir."}];
